using System;
using System.Collections.Generic;
using TMPro;
using UnityEngine;
using UnityEngine.UI;

namespace T2U.Kit
{
    /// <summary>
    /// Named elements of a UI screen generated by the UI layout importer (names = the web's data-ui / data-ui-button).
    /// Game code: refs.Text("hud.score").text = ...; refs.OnClick(id => model.Input(...)); refs.State("shop.buy", "no", true);
    /// refs.Fill("hud.hpFill").Set(0.4f); refs.Show("hud.hint", false).
    /// </summary>
    public sealed class UiRefs : MonoBehaviour
    {
        [Serializable]
        public struct Entry
        {
            public string name;
            public RectTransform rect;
            public string button;
            /// <summary>CSS animation the web plays on this element at rest ("bob 0.9s ease-in-out infinite alternate"), or "".</summary>
            public string anim;
        }

        public string screen;
        public List<Entry> entries = new List<Entry>();
        Dictionary<string, RectTransform> _map;

        public RectTransform Get(string name)
        {
            if (_map == null)
            {
                _map = new Dictionary<string, RectTransform>();
                foreach (var e in entries) _map[e.name] = e.rect;
            }
            return _map.TryGetValue(name, out var r) ? r : throw new KeyNotFoundException($"UI '{screen}' has no element '{name}'");
        }

        public TMP_Text Text(string name) => Get(name).GetComponentInChildren<TMP_Text>(true);
        public Image Image(string name) => Get(name).GetComponent<Image>();

        /// <summary>Calls <paramref name="onClick"/> with the button id (data-ui-button) for every button of the screen.</summary>
        public void OnClick(Action<string> onClick)
        {
            foreach (var e in entries)
            {
                if (string.IsNullOrEmpty(e.button)) continue;
                var id = e.button;
                e.rect.GetComponent<Button>().onClick.AddListener(() => onClick(id));
            }
        }

        public void Show(bool on) => gameObject.SetActive(on);

        /// <summary>Shows or hides one element (web: el.hidden = !on).</summary>
        public void Show(string name, bool on)
        {
            var go = Get(name).gameObject;
            if (go.activeSelf != on) go.SetActive(on);
        }

        UiStates _states;
        /// <summary>Switches a state of an element (web: classList.toggle(state, on)). See <see cref="UiStates"/>.</summary>
        public void State(string name, string state, bool on)
        {
            if (_states == null) _states = GetComponent<UiStates>();
            if (_states != null) _states.Set(name, state, on);
        }

        /// <summary>A bar the game fills (web: data-ui-fill). <c>Fill("army.hpFill").Set(0.4f)</c></summary>
        public UiFill Fill(string name) => Get(name).GetComponent<UiFill>();

        /// <summary>A list (web: data-ui-list): its rows, and new rows from its row prefabs. See <see cref="UiList"/>.</summary>
        public UiList List(string name) => Get(name).GetComponent<UiList>();

        /// <summary>A row of a list by its name ("army.guard"): its elements by suffix (".lv"). See <see cref="UiRow"/>.</summary>
        public UiRow Row(string name) => Get(name).GetComponent<UiRow>();

        /// <summary>A scrolling element (web: overflow auto/scroll). <c>Scroll("army.list").verticalNormalizedPosition = 1</c> = top.</summary>
        public ScrollRect Scroll(string name) => Get(name).GetComponent<ScrollRect>();

        /// <summary>Plays a CSS animation of the element now ("purseBump 0.3s ease-out"), "" stops it. See <see cref="UiAnim"/>.</summary>
        public void Animate(string name, string anim)
        {
            var a = Get(name).GetComponent<UiAnim>();
            if (a != null) a.Play(anim);
        }
    }
}
